// ParseAge разбирает возраст из строки
func ParseAge(s string) (int, error) {
    n, err := strconv.Atoi(s)
    if err != nil {
        return 0, fmt.Errorf("возраст %q: %w", s, err)
    }
    if n < 0 || n > 150 {
        return 0, fmt.Errorf("возраст %d вне диапазона 0…150", n)
    }
    return n, nil
}

func main() {
    fmt.Println(ParseAge("42"))
}

