package main

import (
    "errors"
    "fmt"
)

var ErrNotEnough = errors.New("недостаточно средств")

// Withdraw списывает sum с balance
func Withdraw(balance, sum int) (int, error) {
    if sum <= 0 {
        return balance, fmt.Errorf("сумма должна быть больше нуля: %d", sum)
    }
    if sum > balance {
        return balance, ErrNotEnough
    }
    return balance - sum, nil
}

func main() {
    fmt.Println(Withdraw(1000, 300))
}

