    "fmt"
)

type StockError struct {
    Want, Have int
}

func (e *StockError) Error() string {
    return fmt.Sprintf("нужно %d, на складе %d", e.Want, e.Have)
}

// Reserve резервирует want штук при остатке have
func Reserve(want, have int) error {
    if want <= 0 {
        return errors.New("количество должно быть больше нуля")
    }
    if want > have {
        return &StockError{Want: want, Have: have}
    }
    return nil
}

func main() {
    err := Reserve(5, 2)
    var se *StockError
    if errors.As(err, &se) {
        fmt.Println("не хватает", se.Want-se.Have)
    }
}

