package main

import (
    "errors"
    "testing"
)

func TestReserve(t *testing.T) {
    t.Run("хватает", func(t *testing.T) {
        if err := Reserve(2, 5); err != nil {
            t.Errorf("Reserve(2, 5) = %v, ожидалось nil", err)
        }
    })
    t.Run("ровно столько", func(t *testing.T) {
        if err := Reserve(5, 5); err != nil {
            t.Errorf("Reserve(5, 5) = %v, ожидалось nil", err)
        }
    })
    t.Run("не хватает", func(t *testing.T) {
        err := Reserve(5, 2)
        var se *StockError
        if !errors.As(err, &se) {
            t.Fatalf("Reserve(5, 2) = %v, ожидалась *StockError", err)
        }
        if se.Want != 5 || se.Have != 2 {
            t.Errorf("StockError{Want: %d, Have: %d}, ожидалось Want 5, Have 2", se.Want, se.Have)
        }
    })
    t.Run("ноль штук", func(t *testing.T) {
        err := Reserve(0, 10)
        var se *StockError
        if err == nil || errors.As(err, &se) {
            t.Errorf("Reserve(0, 10) = %v, ожидалась обычная ошибка про количество", err)
        }
    })
}
